// Student growth activities share the existing authoritative classroom actions.
const CROP_TYPES=[{name:'상추',icon:'🥬',ms:20000,yield:2},{name:'당근',icon:'🥕',ms:35000,yield:3},{name:'토마토',icon:'🍅',ms:40000,yield:2},{name:'감자',icon:'🥔',ms:45000,yield:4},{name:'딸기',icon:'🍓',ms:60000,yield:2}];
let selectedCrop=0,growthBoard=null,growthLoading=false;
function cropDuration(p){return CROP_TYPES[p.crop||0].ms}
function growthEscape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const isGrowthCampus=!!document.querySelector('#studyPage');
const growthPanel=document.createElement('section');growthPanel.className='growth-panel';growthPanel.id='growthActivities';growthPanel.innerHTML='<h2>🌱 나의 성장 여권</h2><p>학급으로 입장하면 농사·퀴즈·공부 기록이 도장으로 쌓여요.</p>';
if(isGrowthCampus)document.querySelector('.passport').append(growthPanel);else document.querySelector('#farmScene').after(growthPanel);
async function loadGrowth(){const auth=sessionStorage.getItem('village-student-token');if(!auth||growthLoading||document.hidden)return;growthLoading=true;try{const r=await fetch('/api/growth',{headers:{authorization:'Bearer '+auth},signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('성장 기록을 불러오지 못했어요.');growthBoard=await r.json();drawGrowth()}catch(e){if(!growthBoard)growthPanel.innerHTML='<p>성장 기록 연결을 확인해 주세요.</p><button id="retryGrowth">다시 확인</button>';if(document.querySelector('#retryGrowth'))document.querySelector('#retryGrowth').onclick=loadGrowth}finally{growthLoading=false}}
function drawGrowth(){const d=growthBoard;if(!d)return;const savedQty=Array.from(growthPanel.querySelectorAll('input[id^=cropQty]')).map(x=>[x.id,x.value]),wasOpen=growthPanel.querySelector('details')?.open,focusId=growthPanel.contains(document.activeElement)?document.activeElement.id:null;const badges='<div class="growth-badges">'+d.badges.map(b=>`<article class="growth-badge ${b.earned?'earned':''}"><b>${b.earned?'✦':'○'} ${growthEscape(b.title)}</b><small>${growthEscape(b.reason)}</small>${b.earned?`<time>${new Date(b.earned).toLocaleDateString('ko-KR')} · 획득</time>`:`<progress value="${Math.min(b.value,b.target)}" max="${b.target}"></progress><small>${b.value} / ${b.target}</small>`}</article>`).join('')+'</div>';
const project=d.project,ready=d.crops.every(c=>(project.totals.find(t=>t.crop===c.id)?.qty||0)>=project.goal),step=project.roles.length;
growthPanel.innerHTML=`<h2>🌱 나의 성장 여권</h2><p>누적 도장은 사라지지 않아요. 연속 출석은 ${d.mode==='school'?'교사가 지정한 수업일':'매일'} 기준, 하루 10분 이상 공부하고 마무리 기록을 남기면 인정돼요. 공부 시간은 실제 학습 인증이 아닌 학생 기록입니다.</p><details ${isGrowthCampus?'open':''}><summary>내 스탬프 · ${d.badges.filter(b=>b.earned).length} / ${d.badges.length}</summary>${badges}</details>${isGrowthCampus?'':`<h2>🧺 시즌 ${project.season} · 함께 만드는 소풍 도시락 30개</h2><p>게임 안에서 재료를 기부하고 포장 → 운송 → 조리 역할을 이어가요. 직접 재배하거나 장터에서 교환한 작물을 판매·기부할 수 있어요. 판매가는 날씨 시세를 반영하고 장터가 닫히면 시세의 80%를 적용해요.</p><div class="crop-inventory">${d.crops.map(c=>`<article><b>${c.icon} ${c.name}</b><span>내 재고 ${d.stock[c.id]}개</span><small>공동 재료 ${project.totals.find(t=>t.crop===c.id)?.qty||0} / ${project.goal}</small><label>수량<input type="number" min="1" max="50" value="1" id="cropQty${c.id}"></label><button data-crop-donate="${c.id}" ${!d.stock[c.id]||d.paused||step===3?'disabled':''}>기부</button><button data-crop-sell="${c.id}" ${!d.stock[c.id]||d.paused?'disabled':''}>판매 · 개당 ${c.price}코인</button></article>`).join('')}</div><div class="garden-steps">${project.stages.map((s,i)=>`<span>${i<step?'✓':i===step&&ready?'→':'○'} ${s.title}</span>`).join('')}</div>${project.history.length?`<p>최근 완성: ${project.history.map(h=>'시즌 '+h.season+' · '+h.participants+'명 참여').join(' / ')} · 초과 재료는 다음 시즌으로 이월돼요.</p>`:''}${project.automatic?'<p>완성하면 다음 시즌이 자동으로 시작돼요.</p>':'<p>완성 후 선생님이 다음 시즌을 열어요.</p>'}${step===3?'<p class="garden-success">🎉 우리 반 공동 도시락 완성! 참여한 친구의 여권에 도장이 찍혀요.</p>':ready?`<h3>${project.stages[step].question}</h3>${project.stages[step].answers.map((s,i)=>`<button data-garden-step="${step}" data-garden-answer="${i}">${growthEscape(s)}</button>`).join('')}`:'<p>다섯 작물을 30개씩 모으면 포장 역할이 열려요. 친구들과 재배할 작물을 나눠 보세요.</p>'}`}`;
for(const [id,value]of savedQty){const input=document.getElementById(id);if(input)input.value=value}if(wasOpen!==undefined)growthPanel.querySelector('details').open=wasOpen;if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});
}
growthPanel.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||isGrowthCampus)return;let action;if(b.dataset.cropDonate!==undefined||b.dataset.cropSell!==undefined){const crop=Number(b.dataset.cropDonate??b.dataset.cropSell),qty=Number(document.querySelector('#cropQty'+crop).value);action={action:b.dataset.cropDonate!==undefined?'crop_donate':'crop_sell',crop,qty,season:growthBoard.project.season}}if(b.dataset.gardenStep!==undefined)action={action:'garden_role',step:Number(b.dataset.gardenStep),answer:Number(b.dataset.gardenAnswer),season:growthBoard.project.season};if(action){b.disabled=true;try{await schoolAction(action)}finally{await loadGrowth()}}});
if(!isGrowthCampus){
const seeds=document.createElement('div');seeds.className='seed-picker';seeds.innerHTML='<b>심을 씨앗</b>'+CROP_TYPES.map((c,i)=>`<button data-seed="${i}" aria-pressed="${i===0}">${c.icon} ${c.name}<small>${c.ms/1000}초 · ${c.yield}개${i===2?' · 3회 수확':''}</small></button>`).join('');document.querySelector('.farm-guide').after(seeds);seeds.onclick=e=>{const b=e.target.closest('[data-seed]');if(!b)return;if(!window.classroomActive){toast('다양한 작물은 학급으로 입장한 뒤 재배할 수 있어요.');return}selectedCrop=Number(b.dataset.seed);seeds.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));toast(CROP_TYPES[selectedCrop].name+' 씨앗 선택 · 빈 밭을 눌러 주세요.')};
const baseGrowthAction=schoolAction;schoolAction=async function(payload){if(payload.action==='plant')payload.crop=selectedCrop;const ok=await baseGrowthAction(payload);if(ok&&payload.action!=='place')await loadGrowth();return ok};
plotStage=function(p,now=Date.now()){if(!p.seeded)return 0;if(!p.wateredAt)return 1;const t=Math.max(0,now-p.wateredAt),ms=cropDuration(p);return t<ms*.4?2:t<ms?3:4};
const baseGrowthPlots=updatePlots;updatePlots=function(){baseGrowthPlots();for(const [i,p]of ensureFarm().plots.entries()){const el=document.querySelector('[data-plot="'+i+'"]');if(!el)continue;const c=CROP_TYPES[p.crop||0],stage=plotStage(p),secs=Math.max(0,Math.ceil((c.ms-(Date.now()-p.wateredAt))/1000));el.dataset.crop=p.crop||0;el.querySelector('.sprite').textContent=p.crop&&stage>=2?(stage===2?'🌱':c.icon):'';el.querySelector('.plot-label').textContent=stage===0?'씨앗 심기':stage===1?c.name+' · 물 주세요':stage===4?c.icon+' '+c.name+' 수확':c.name+' · '+secs+'초';el.querySelector('.plot-meter i').style.width=Math.min(100,Math.max(0,(Date.now()-p.wateredAt)/c.ms*100))+'%'}const heading=document.querySelector('.farm-top h2'),title=farmView?'내가 가꾸는 텃밭':'우리 반 연결 마을';if(heading.textContent!==title)heading.textContent=title;document.querySelector('#farmView').textContent='🌱 내 텃밭';};
const baseGrowthQuiz=quiz;quiz=function(kind='daily'){if(kind!=='daily'||!window.classroomActive){baseGrowthQuiz(kind);return}if(!growthBoard){loadGrowth();toast('퀴즈를 준비 중이에요. 잠시 뒤 다시 눌러 주세요.');return}const q=growthBoard.quiz;if(!q){toast('50가지 직업 문제를 모두 해결했어요!');return}modal(`<h2>오늘의 직업 탐험</h2><p>${growthEscape(q.prompt)}</p>${q.answers.map((a,i)=>`<button class="wide" data-growth-answer="${i}">${growthEscape(a)}</button>`).join('')}<p id="growthQuizFeedback" role="status"></p><button data-close>나중에 풀기</button>`);document.querySelectorAll('[data-growth-answer]').forEach(b=>b.onclick=async()=>{const ok=await schoolAction({action:'quiz',quizId:q.id,answer:Number(b.dataset.growthAnswer)});if(ok){close();toast('정답! 20코인과 직업 탐험 기록을 받았어요.')}else if(document.querySelector('#growthQuizFeedback'))document.querySelector('#growthQuizFeedback').textContent='다시 생각해 보세요. 오늘 보상을 이미 받았거나 수업이 쉬는 중인지도 확인해 주세요.'})};
const oldGrowthRender=render;render=function(){oldGrowthRender();if(farmView){document.querySelector('.eyebrow').textContent='CHAPTER 01 · 다섯 빛깔 텃밭';const desc=document.querySelector('#phaseDesc');if(desc)desc.textContent='작물마다 20~60초 · 토마토는 한 번 심어 3회 수확';const p=document.querySelector('#panel p');const stats=document.querySelectorAll('.farm-mini-stats span');if(stats[0])stats[0].textContent='직접 수확한 작물';const hint=document.querySelector('.farm-saved');if(hint)hint.textContent='상추 외 작물은 아래 작물 보관함에서 판매·기부해요. 기존 물건과 코인은 유지됩니다.';if(p)p.textContent='씨앗을 고르고 빈 밭에 심어 물을 주세요. 상추 20초, 당근 35초, 토마토 40초, 감자 45초, 딸기 60초. 실제 재배와 다른 체험 속도예요.'}};
}else{const baseGrowthDisplay=display;display=function(d){baseGrowthDisplay(d);if(growthBoard)drawGrowth()};const baseGrowthAct=act;act=async function(path,b){const d=await baseGrowthAct(path,b);if(d&&b.action==='finish')await loadGrowth();return d}}
loadGrowth();const firstGrowth=setInterval(()=>{if(sessionStorage.getItem('village-student-token')){clearInterval(firstGrowth);if(!growthBoard)loadGrowth()}},1000);setInterval(()=>{if(!document.hidden)loadGrowth()},30000);
